import java.util.Scanner;
import java.lang.*;

public class cf723b {

	static final Scanner sc = new Scanner(System.in);
	static int[] documentAnalyser(String doc) {
		boolean insideParenthesis = false;
		boolean lastWasLetter = false;

		int longestLength = 0;
		int wordLength = 0;

		int wordsInParentheses = 0;

		for (int i = 0; i < doc.length(); ++i) {
			if (doc.charAt(i) == '(') {
				insideParenthesis = true;
				lastWasLetter = false;
				wordLength = 0;
			}
			else if (doc.charAt(i) == ')') {
				insideParenthesis = false;
				lastWasLetter = false;
				wordLength = 0;
			}
			else if (Character.isLetter(doc.charAt(i))) {
				if (insideParenthesis && !lastWasLetter) {
					wordsInParentheses += 1;
				}
				else if (!insideParenthesis) {
					wordLength += 1;
					longestLength = Math.max(wordLength, longestLength);
				}
				lastWasLetter = true;
			}
			else {
				lastWasLetter = false;
				wordLength = 0;
			}	
		}
		int[] valuesOfInterest = {longestLength, wordsInParentheses};
		return valuesOfInterest;
	}
	public static void main(String[] args) {
		int stringLength = sc.nextInt();
		String doc = sc.next();
		int[] analysis = new int[2];
		analysis = documentAnalyser(doc);
		System.out.print(analysis[0] + " " + analysis[1]);
	}
}

